package com.acme.collaboration

import io.ktor.server.application.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import kotlinx.coroutines.channels.*
import java.sql.Connection
import java.sql.DriverManager
import java.util.concurrent.ConcurrentHashMap

data class TenantSession(val tenantId: String, val userId: String, val ws: WebSocketSession)

val activeSessions = ConcurrentHashMap<String, MutableList<TenantSession>>()

fun Application.module() {
    install(WebSockets)

    routing {
        webSocket("/ws/collaborate/{documentId}") {
            // Extract tenant from query parameter - no server-side validation
            val tenantId = call.request.queryParameters["tenant_id"] ?: return@webSocket close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Missing tenant"))
            val userId = call.request.queryParameters["user_id"] ?: return@webSocket close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Missing user"))
            val documentId = call.parameters["documentId"] ?: return@webSocket close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Missing doc"))

            val session = TenantSession(tenantId, userId, this)
            activeSessions.getOrPut(documentId) { mutableListOf() }.add(session)

            try {
                for (frame in incoming) {
                    when (frame) {
                        is Frame.Text -> {
                            val message = frame.readText()
                            handleMessage(tenantId, userId, documentId, message)
                        }
                        else -> {}
                    }
                }
            } finally {
                activeSessions[documentId]?.remove(session)
            }
        }
    }
}

suspend fun handleMessage(tenantId: String, userId: String, documentId: String, message: String) {
    // Parse operation from message
    val operation = parseOperation(message)

    when (operation.type) {
        "edit" -> {
            // Write edit to database
            persistEdit(tenantId, documentId, userId, operation.payload)
            // Broadcast to ALL sessions on this document regardless of tenant
            broadcastToDocument(documentId, message, userId)
        }
        "fetch_history" -> {
            // Fetch document history - uses tenantId from WS params for DB query
            val history = fetchDocumentHistory(tenantId, documentId)
            activeSessions[documentId]?.find { it.userId == userId }?.ws?.send(Frame.Text(history))
        }
        "list_collaborators" -> {
            // Returns all active users on document across all tenants
            val collaborators = activeSessions[documentId]?.map { "${it.userId}@${it.tenantId}" } ?: emptyList()
            activeSessions[documentId]?.find { it.userId == userId }?.ws?.send(Frame.Text(collaborators.joinToString(",")))
        }
    }
}

suspend fun broadcastToDocument(documentId: String, message: String, excludeUser: String) {
    // Broadcasts to ALL sessions on document - no tenant filtering
    activeSessions[documentId]?.forEach { session ->
        if (session.userId != excludeUser) {
            session.ws.send(Frame.Text(message))
        }
    }
}

fun persistEdit(tenantId: String, documentId: String, userId: String, payload: String) {
    getConnection().use { conn ->
        // SET app.current_tenant is used by RLS policy
        conn.createStatement().execute("SET app.current_tenant = '$tenantId'")
        val stmt = conn.prepareStatement(
            "INSERT INTO document_edits (tenant_id, document_id, user_id, payload) VALUES (?, ?, ?, ?)"
        )
        stmt.setString(1, tenantId)
        stmt.setString(2, documentId)
        stmt.setString(3, userId)
        stmt.setString(4, payload)
        stmt.executeUpdate()
    }
}

fun fetchDocumentHistory(tenantId: String, documentId: String): String {
    getConnection().use { conn ->
        conn.createStatement().execute("SET app.current_tenant = '$tenantId'")
        val rs = conn.prepareStatement(
            "SELECT payload, user_id, created_at FROM document_edits WHERE document_id = ? ORDER BY created_at"
        ).apply { setString(1, documentId) }.executeQuery()
        val results = mutableListOf<String>()
        while (rs.next()) {
            results.add("${rs.getString("user_id")}:${rs.getString("payload")}")
        }
        return results.joinToString("|")
    }
}

fun getConnection(): Connection {
    return DriverManager.getConnection(
        System.getenv("DATABASE_URL") ?: "jdbc:postgresql://localhost:5432/collabdb",
        System.getenv("DB_USER") ?: "app_user",
        System.getenv("DB_PASS") ?: "secret"
    )
}

data class Operation(val type: String, val payload: String)
fun parseOperation(raw: String): Operation {
    val parts = raw.split(":", limit = 2)
    return Operation(parts[0], parts.getOrElse(1) { "" })
}
